#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2005;

int n;
ll P, pw[N], f[N][N], g[N][N], h[N][N], t[N], ans[N], sum;

ll qpow(ll a, ll b)
{
	ll res = 1;
	while (b)
	{
		if (b & 1)
			(res *= a) %= P;
		(a *= a) %= P;
		b >>= 1;
	}
	return res;
}

void init() {}

void solve()
{
	cin >> n >> P;
	pw[0] = 1;
	for (int i = 1; i <= n; ++i)
		pw[i] = (pw[i - 1] << 1) % P;
	f[0][0] = g[0][0] = h[1][0] = 1;
	for (int i = 1; i < n; ++i)
	{
		for (int j = 1; j < i; ++j)
			f[i][j] = (pw[i - j] * f[i - 1][j - 1] + pw[i - j - 1] * f[i - 1][j]) % P;
		f[i][i] = f[i - 1][i - 1];
	}
	for (int i = 1; i < n; ++i)
	{
		for (int j = 1; j <= i; ++j)
			g[i][j] = (g[i - 1][j - 1] + (pw[i - 1] - 1) * g[i - 1][j]) % P;
	}
	for (int i = 1; i < n; ++i)
	{
		for (int j = 1; j < i; ++j)
		{
			(h[i][j] = ((pw[i - j - 1] - 1) * h[i - 1][j] - (pw[i - j] - 1) * h[i - 1][j - 1]) % P) <= 0 ? h[i][j] += P : 0;
			(t[i + 1] += (pw[i - j] - 1) * h[i][j]) %= P;
		}
		h[i][i] = -1;
	}
	for (int i = 1; i <= n; ++i)
	{
		for (int j = i; j <= n; ++j)
			(ans[i] += pw[n - j] * f[n - 1][j - 1] * g[j - 1][i - 1]) %= P;
		(sum += (ans[i] *= t[i]) %= P) >= P ? sum -= P : 0;
	}
	(ans[0] = qpow(2, n * (n - 1) >> 1) - sum) < 0 ? ans[0] += P : 0;
	for (int i = 0; i <= n; ++i)
		cout << ans[i] << " \n"[i == n];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

